        let autoApplyAt = 0;
        let autoApplyBuild = '';
        let autoApplyTimer = 0;
        let lastInputAt = 0;   // 0 = nobody has touched this page yet
        let readySinceAt = 0;  // when this tab first saw the build as newer
        // A tab that reloaded itself for an update shows the finished line once,
        // on the build it landed on. sessionStorage survives the reload and the
