        // Real build time and real server uptime, taken straight from the live
        // snapshot (build.builtAt is the moment dist/index.html was written;
        // server.uptimeSec is the running server's own process uptime). The
        // uptime is re-painted once a second from that measured base, so the
        // corner shows a clock that climbs — not a number frozen at page load.
        const pad2 = (n) => String(n).padStart(2, '0');
        // Bottom-right corner of the card: when the builds were measured
