            row('reason', String(st.reason || '—'));
            const ev = st.evidence;
            if (ev) row('evidence', ev.passing + '/' + ev.checks + ' pass · measured ' + (ev.measured == null ? '?' : ev.measured) + ' · pass ratio ' + ev.ratio + ' · evidence ratio ' + (ev.evidenceRatio == null ? ev.ratio : ev.evidenceRatio));
            const heal = st.heal;
            if (heal) row('heal', (heal.healed && heal.healed.length ? 'retry saved ' + heal.healed.join(',') : 'no retry needed') + (heal.escalated && heal.escalated.length ? ' · escalated ' + heal.escalated.join(',') : '') + ' · retry only, no restart');
            const wd = st.watchdog;
            if (wd) row('watchdog', (wd.stale ? 'STALE' : 'ok') + ' · evidence ' + (wd.evidenceAgeSec == null ? '?' : wd.evidenceAgeSec) + 's old');
